<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\Product;use Illuminate\Http\Request;
class ProductController extends Controller {public function index(Request $r){$q=Product::query();if($s=$r->query('search'))$q->where(fn($w)=>$w->where('product_name','ilike',"%$s%")->orWhere('product_code','ilike',"%$s%"));$sort=in_array($r->query('sort'),['product_name','price','stock','created_at'])?$r->query('sort'):'created_at';$p=$q->orderBy($sort,$r->query('direction')==='asc'?'asc':'desc')->paginate(min((int)$r->query('per_page',10),100));return response()->json(['success'=>true,'message'=>'OK','data'=>$p->items(),'meta'=>['page'=>$p->currentPage(),'per_page'=>$p->perPage(),'total'=>$p->total(),'total_pages'=>$p->lastPage()]]);}public function store(Request $r){abort_unless($r->user()->isAdmin(),403);$v=$r->validate(['product_code'=>'required|string|max:50|unique:products','product_name'=>'required|string|max:255','stock'=>'required|integer|min:0','price'=>'required|numeric|gt:0','low_stock_threshold'=>'required|integer|min:0']);return response()->json(['success'=>true,'message'=>'Created','data'=>Product::create($v)],201);}public function show(Product $product){return response()->json(['success'=>true,'message'=>'OK','data'=>$product]);}public function update(Request $r,Product $product){abort_unless($r->user()->isAdmin(),403);$v=$r->validate(['product_code'=>'sometimes|required|string|unique:products,product_code,'.$product->id,'product_name'=>'sometimes|required|string','stock'=>'sometimes|required|integer|min:0','price'=>'sometimes|required|numeric|gt:0','low_stock_threshold'=>'sometimes|required|integer|min:0']);$product->update($v);return response()->json(['success'=>true,'message'=>'Updated','data'=>$product]);}public function destroy(Request $r,Product $product){abort_unless($r->user()->isAdmin(),403);$product->delete();return response()->noContent();}}
